// Источник — по адресу сайта; свежие — за последние сутки, не больше пяти с каждого сайта.
const names = { 'habr.com': 'Хабр', 'naked-science.ru': 'Naked Science', 'www.ixbt.com': 'iXBT' }
const dayAgo = Date.now() - 24 * 60 * 60 * 1000
const perSource = {}
const result = []
for (const item of $input.all()) {
  const news = item.json
  if (typeof news.link !== 'string' || !/^https?:\/\//i.test(news.link)) continue
  const link = news.link.split('?')[0]
  const site = link.split('/')[2]
  const source = names[site] ?? site
  const time = new Date(news.isoDate ?? news.pubDate).getTime()
  perSource[source] = (perSource[source] ?? 0)
  if (!Number.isFinite(time) || time > Date.now() || time < dayAgo || perSource[source] >= 5) continue
  perSource[source]++
  result.push({ json: {
    id: link,
    date: new Date(time).toISOString(),
    source,
    title: news.title,
    text: (news.contentSnippet || news['content:encodedSnippet'] || '').replace(/\s+/g, ' ').slice(0, 1500),
    link,
  } })
}
if (!result.length && $input.all().every((item) => item.json.error)) throw new Error('Все RSS-ленты недоступны')
return result

