// Ответ модели проверяется: теги только из списка, пустой пересказ — новость пропускается.
const allowed = ["ИИ", "программирование", "безопасность", "железо", "смартфоны", "наука", "игры", "бизнес", "интернет"]
const fresh = $('Свежие новости').all()
const result = []
$input.all().forEach((item, i) => {
  const news = fresh[i].json
  let answer
  try {
    answer = JSON.parse(item.json.message.content)
  } catch {
    return
  }
  const summary = typeof answer.summary === 'string' ? answer.summary.trim() : ''
  const tags = (Array.isArray(answer.tags) ? answer.tags : []).filter((tag) => allowed.includes(tag)).slice(0, 3)
  if (!summary || !tags.length) return
  result.push({ json: { id: news.id, date: news.date, source: news.source, title: news.title, summary, tags, link: news.link } })
})
return result

